class Message {
    private final String messageId;   // unique id, e.g. M1
    private final String topic;         // the topic it was published to
    private final String payload;         // the message body
    private int deliveryCount;              // how many times this has been delivered so far

    public Message(String messageId, String topic, String payload) {
        this.messageId = messageId; // store id
        this.topic = topic;           // store topic
        this.payload = payload;        // store payload
        this.deliveryCount = 0;          // never delivered yet
    }

    public String getMessageId() { return messageId; } // id getter
    public String getTopic() { return topic; }             // topic getter
    public String getPayload() { return payload; }            // payload getter
    public int getDeliveryCount() { return deliveryCount; }       // delivery count getter
    public void incrementDeliveryCount() { deliveryCount++; }        // bump delivery count on each redelivery
}

// One consumer, with its own pending queue, in-flight tracking, and dead-letter list.
class Subscriber {
    private final String subscriberId;                                                  // unique id
    private final java.util.List<String> topicPatterns = new java.util.ArrayList<>();       // registered patterns
    private final java.util.List<Message> pendingQueue = new java.util.LinkedList<>();         // messages waiting to be received
    private final java.util.Map<String, Integer> inFlightDeliveredAtTick = new java.util.LinkedHashMap<>(); // messageId -> tick it was delivered at
    private final java.util.Map<String, Message> inFlightMessages = new java.util.LinkedHashMap<>();           // messageId -> the message itself
    private final java.util.List<Message> deadLetterList = new java.util.ArrayList<>();                    // messages that exhausted their retries

    public Subscriber(String subscriberId) {
        this.subscriberId = subscriberId; // store id
    }

    public String getSubscriberId() { return subscriberId; }              // id getter
    public java.util.List<String> getTopicPatterns() { return topicPatterns; } // registered patterns getter
    public void addPattern(String pattern) { topicPatterns.add(pattern); }        // register a new pattern
    public void enqueue(Message message) { pendingQueue.add(message); }             // add a message to the back of the pending queue
    public boolean hasPending() { return !pendingQueue.isEmpty(); }                    // true if anything is waiting to be received
    public Message dequeueFront() { return ((java.util.LinkedList<Message>) pendingQueue).removeFirst(); } // remove and return the front message
    public void requeueFront(Message message) { ((java.util.LinkedList<Message>) pendingQueue).addFirst(message); } // put a message back at the front for priority redelivery
    public void markInFlight(Message message, int tick) {                                // record that a message is now awaiting acknowledgment
        inFlightMessages.put(message.getMessageId(), message);
        inFlightDeliveredAtTick.put(message.getMessageId(), tick);
    }
    public boolean isInFlight(String messageId) { return inFlightMessages.containsKey(messageId); } // check if a message is currently awaiting acknowledgment
    public void clearInFlight(String messageId) {                                          // remove a message from in-flight tracking
        inFlightMessages.remove(messageId);
        inFlightDeliveredAtTick.remove(messageId);
    }
    public java.util.Map<String, Message> getInFlightMessages() { return inFlightMessages; }     // full in-flight map getter
    public java.util.Map<String, Integer> getInFlightDeliveredAtTick() { return inFlightDeliveredAtTick; } // full delivered-at-tick map getter
    public void addToDeadLetter(Message message) { deadLetterList.add(message); }                  // move a message into the dead letter list
    public java.util.List<Message> getDeadLetterList() { return deadLetterList; }                     // dead letter list getter
}

