// Strategy interface: how a subscription pattern compares against a published topic.
interface TopicMatchingStrategy {
    boolean matches(String pattern, String topic); // true if this pattern should receive this topic's messages
}

// The topic string must equal the pattern exactly.
class ExactTopicMatchingStrategy implements TopicMatchingStrategy {
    @Override
    public boolean matches(String pattern, String topic) {
        return pattern.equals(topic); // exact string equality, nothing more
    }
}

// Same segment count required, a star segment matches any single segment.
class WildcardTopicMatchingStrategy implements TopicMatchingStrategy {
    @Override
    public boolean matches(String pattern, String topic) {
        String[] patternParts = pattern.split("\\.");    // split the pattern into dot separated segments
        String[] topicParts = topic.split("\\.");           // split the topic the same way
        if (patternParts.length != topicParts.length) return false; // different segment counts never match
        for (int i = 0; i < patternParts.length; i++) {                // compare segment by segment
            if (!patternParts[i].equals("*") && !patternParts[i].equals(topicParts[i])) return false; // a non wildcard segment must match exactly
        }
        return true; // every segment agreed, or was a wildcard
    }
}

// Observer interface: reacts to pub-sub lifecycle events.
interface DeliveryObserver {
    void onMessagePublished(String topic, int matchedCount);            // a message was routed to some number of subscribers
    void onMessageAcknowledged(String subscriberId, String messageId);     // a subscriber confirmed successful processing
    void onMessageDeadLettered(String subscriberId, Message message);        // a message exhausted its retries
}

// Simple observer that prints events to the console.
class ConsoleDeliveryObserver implements DeliveryObserver {
    @Override
    public void onMessagePublished(String topic, int matchedCount) {
        System.out.println("Published to " + topic + ", matched " + matchedCount + " subscriber(s)");
    }

    @Override
    public void onMessageAcknowledged(String subscriberId, String messageId) {
        System.out.println("Acknowledged " + messageId + " for " + subscriberId);
    }

    @Override
    public void onMessageDeadLettered(String subscriberId, Message message) {
        System.out.println("Dead lettered " + message.getMessageId() + " for " + subscriberId);
    }
}

