#include <string>
#include <vector>
#include <sstream>
#include <iostream>
using namespace std;

// Splits a dot separated string into its segments.
vector<string> splitBySegment(const string& value) {
    vector<string> parts;              // accumulated segments
    stringstream stream(value);           // stream over the input
    string segment;                          // one segment at a time
    while (getline(stream, segment, '.')) parts.push_back(segment); // split on every dot
    return parts; // the full list of segments
}

// Strategy interface: how a subscription pattern compares against a published topic.
class TopicMatchingStrategy {
public:
    virtual bool matches(const string& pattern, const string& topic) = 0;
    virtual ~TopicMatchingStrategy() {}
};

// The topic string must equal the pattern exactly.
class ExactTopicMatchingStrategy : public TopicMatchingStrategy {
public:
    bool matches(const string& pattern, const string& topic) override {
        return pattern == topic; // exact string equality, nothing more
    }
};

// Same segment count required, a star segment matches any single segment.
class WildcardTopicMatchingStrategy : public TopicMatchingStrategy {
public:
    bool matches(const string& pattern, const string& topic) override {
        vector<string> patternParts = splitBySegment(pattern);    // split the pattern into dot separated segments
        vector<string> topicParts = splitBySegment(topic);           // split the topic the same way
        if (patternParts.size() != topicParts.size()) return false;     // different segment counts never match
        for (size_t i = 0; i < patternParts.size(); i++) {                  // compare segment by segment
            if (patternParts[i] != "*" && patternParts[i] != topicParts[i]) return false; // a non wildcard segment must match exactly
        }
        return true; // every segment agreed, or was a wildcard
    }
};

// Observer interface: reacts to pub-sub lifecycle events.
class DeliveryObserver {
public:
    virtual void onMessagePublished(const string& topic, int matchedCount) = 0;
    virtual void onMessageAcknowledged(const string& subscriberId, const string& messageId) = 0;
    virtual void onMessageDeadLettered(const string& subscriberId, const Message& message) = 0;
    virtual ~DeliveryObserver() {}
};

// Simple observer that prints events to the console.
class ConsoleDeliveryObserver : public DeliveryObserver {
public:
    void onMessagePublished(const string& topic, int matchedCount) override {
        cout << "Published to " << topic << ", matched " << matchedCount << " subscriber(s)" << endl;
    }
    void onMessageAcknowledged(const string& subscriberId, const string& messageId) override {
        cout << "Acknowledged " << messageId << " for " << subscriberId << endl;
    }
