// Custom exceptions for the realistic failure modes.
class InvalidTopicPatternException extends RuntimeException {
    public InvalidTopicPatternException(String msg) { super(msg); }
}
class EmptyQueueException extends RuntimeException {
    public EmptyQueueException(String msg) { super(msg); }
}
class InvalidAcknowledgmentException extends RuntimeException {
    public InvalidAcknowledgmentException(String msg) { super(msg); }
}

// The core message routing engine tying every piece together.
class PubSubService {
    private final java.util.Map<String, Subscriber> subscribers = new java.util.LinkedHashMap<>(); // subscriberId -> Subscriber
    private final java.util.List<DeliveryObserver> observers = new java.util.ArrayList<>();      // listeners
    private final ExactTopicMatchingStrategy exactStrategy = new ExactTopicMatchingStrategy();       // reused exact matcher
    private final WildcardTopicMatchingStrategy wildcardStrategy = new WildcardTopicMatchingStrategy(); // reused wildcard matcher
    private int currentTick = 0;                                                                          // deterministic logical clock
    private final int maxRetries;                                                                            // redelivery attempts allowed before dead lettering
    private final int timeoutTicks;                                                                             // ticks an in-flight message may wait before timing out

    public PubSubService(int maxRetries, int timeoutTicks) {
        this.maxRetries = maxRetries;       // store retry limit
        this.timeoutTicks = timeoutTicks;     // store timeout window
    }

    public void addObserver(DeliveryObserver observer) { observers.add(observer); } // register a listener

    public Subscriber subscriberFor(String subscriberId) {
        return subscribers.computeIfAbsent(subscriberId, Subscriber::new); // create the subscriber on first use
    }

    private TopicMatchingStrategy strategyFor(String pattern) {
        return pattern.contains("*") ? wildcardStrategy : exactStrategy; // a wildcard character selects the wildcard strategy
    }

    // Registers interest in an exact topic or a wildcard pattern.
    public void subscribe(String subscriberId, String pattern) {
        if (pattern == null || pattern.trim().isEmpty()) { // blank patterns are not allowed
            throw new InvalidTopicPatternException("Topic pattern must not be blank");
        }
        subscriberFor(subscriberId).addPattern(pattern); // register the pattern
    }

    // Routes one message copy to every subscriber with at least one matching subscription.
    public int publish(String topic, String payload, MessageIdFactory factory) {
        int matchedCount = 0;                                                          // how many subscribers matched
        for (Subscriber subscriber : subscribers.values()) {                              // scan every registered subscriber
            boolean matched = false;                                                         // has this subscriber already matched this publish
            for (String pattern : subscriber.getTopicPatterns()) {                              // scan every one of their patterns
                if (strategyFor(pattern).matches(pattern, topic)) { matched = true; break; }        // one match is enough
            }
            if (matched) {                                                                        // enqueue exactly one copy for this subscriber
                Message message = new Message(factory.nextMessageId(), topic, payload);
                subscriber.enqueue(message);
                matchedCount++;
            }
        }
        for (DeliveryObserver obs : observers) obs.onMessagePublished(topic, matchedCount); // notify
        return matchedCount; // how many subscribers received a copy
    }

    // Dequeues the next pending message for a subscriber, marking it in flight.
    public synchronized Message receive(String subscriberId) {
        Subscriber subscriber = subscriberFor(subscriberId);          // the subscriber pulling a message
        if (!subscriber.hasPending()) {                                  // nothing waiting
            throw new EmptyQueueException("No pending messages for " + subscriberId);
        }
        Message message = subscriber.dequeueFront();                        // take the front of the queue
        subscriber.markInFlight(message, currentTick);                         // start tracking it as awaiting acknowledgment
        return message; // hand back the message now in flight
    }

    // Confirms successful processing of an in-flight message.
    public void acknowledge(String subscriberId, String messageId) {
        Subscriber subscriber = subscriberFor(subscriberId);          // the subscriber acknowledging
        if (!subscriber.isInFlight(messageId)) {                         // this message is not currently awaiting acknowledgment
            throw new InvalidAcknowledgmentException(messageId + " is not in flight for " + subscriberId);
        }
        subscriber.clearInFlight(messageId);                                 // done, stop tracking it
        for (DeliveryObserver obs : observers) obs.onMessageAcknowledged(subscriberId, messageId); // notify
    }

    public void advanceTick() { currentTick++; } // advances the deterministic logical clock by one step

    // Sweeps every subscriber's in-flight messages, redelivering or dead-lettering anything that has timed out.
    public void checkForRedelivery() {
        for (Subscriber subscriber : subscribers.values()) {                                                       // scan every subscriber
            java.util.List<String> timedOut = new java.util.ArrayList<>();                                             // ids that have timed out this sweep
            for (java.util.Map.Entry<String, Integer> entry : subscriber.getInFlightDeliveredAtTick().entrySet()) {        // scan every in-flight message
                if (currentTick-entry.getValue() >= timeoutTicks) timedOut.add(entry.getKey()); // this one has waited too long
            }
            for (String messageId : timedOut) {                                                                          // handle each timed out message
                Message message = subscriber.getInFlightMessages().get(messageId);                                          // the message itself
                subscriber.clearInFlight(messageId);                                                                           // no longer in flight
                message.incrementDeliveryCount();                                                                                // this counts as a failed attempt
                if (message.getDeliveryCount() > maxRetries) {                                                                     // retries exhausted
                    subscriber.addToDeadLetter(message);                                                                              // set it aside permanently
                    for (DeliveryObserver obs : observers) obs.onMessageDeadLettered(subscriber.getSubscriberId(), message);
                } else {                                                                                                              // still has attempts left
                    subscriber.requeueFront(message);                                                                                    // redeliver it next
                }
            }
        }
    }
}

