#include <string>
#include <vector>
#include <map>
#include <memory>
#include <stdexcept>
using namespace std;

// Custom exceptions for the realistic failure modes.
class InvalidTopicPatternException : public runtime_error {
public: InvalidTopicPatternException(const string& msg) : runtime_error(msg) {}
};
class EmptyQueueException : public runtime_error {
public: EmptyQueueException(const string& msg) : runtime_error(msg) {}
};
class InvalidAcknowledgmentException : public runtime_error {
public: InvalidAcknowledgmentException(const string& msg) : runtime_error(msg) {}
};

// The core message routing engine tying every piece together.
class PubSubService {
    map<string, Subscriber> subscribers;                 // subscriberId -> Subscriber
    vector<shared_ptr<DeliveryObserver>> observers;          // listeners
    ExactTopicMatchingStrategy exactStrategy;                   // reused exact matcher
    WildcardTopicMatchingStrategy wildcardStrategy;                // reused wildcard matcher
    int currentTick = 0;                                              // deterministic logical clock
    int maxRetries;                                                      // redelivery attempts allowed before dead lettering
    int timeoutTicks;                                                       // ticks an in-flight message may wait before timing out

    Subscriber& subscriberFor(string subscriberId) {
        if (subscribers.find(subscriberId) == subscribers.end()) subscribers[subscriberId] = Subscriber(subscriberId); // create on first use
        return subscribers.at(subscriberId);
    }

    TopicMatchingStrategy& strategyFor(string pattern) {
        if (pattern.find('*') != string::npos) return wildcardStrategy; // a wildcard character selects the wildcard strategy
        return exactStrategy;
    }

public:
    PubSubService(int retries, int timeout) : maxRetries(retries), timeoutTicks(timeout) {} // store retry limit and timeout window

    void addObserver(shared_ptr<DeliveryObserver> observer) { observers.push_back(observer); } // register a listener

    void subscribe(string subscriberId, string pattern) {
        if (pattern.empty()) throw InvalidTopicPatternException("Topic pattern must not be blank"); // blank patterns are not allowed
        subscriberFor(subscriberId).addPattern(pattern); // register the pattern
    }

    int publish(string topic, string payload, MessageIdFactory& factory) {
        int matchedCount = 0;                                                          // how many subscribers matched
        for (auto& pair : subscribers) {                                                  // scan every registered subscriber
            Subscriber& subscriber = pair.second;
            bool matched = false;                                                            // has this subscriber already matched this publish
            for (auto& pattern : subscriber.topicPatterns) {                                     // scan every one of their patterns
                if (strategyFor(pattern).matches(pattern, topic)) { matched = true; break; }         // one match is enough
            }
            if (matched) {                                                                        // enqueue exactly one copy for this subscriber
                Message message(factory.nextMessageId(), topic, payload);
                subscriber.enqueue(message);
                matchedCount++;
            }
        }
        for (auto& obs : observers) obs->onMessagePublished(topic, matchedCount); // notify
        return matchedCount; // how many subscribers received a copy
    }

    Message receive(string subscriberId) {
        Subscriber& subscriber = subscriberFor(subscriberId);          // the subscriber pulling a message
        if (!subscriber.hasPending()) throw EmptyQueueException("No pending messages for " + subscriberId); // nothing waiting
        Message message = subscriber.dequeueFront();                       // take the front of the queue
        subscriber.markInFlight(message, currentTick);                        // start tracking it as awaiting acknowledgment
        return message; // hand back the message now in flight
    }

    void acknowledge(string subscriberId, string messageId) {
        Subscriber& subscriber = subscriberFor(subscriberId);          // the subscriber acknowledging
        if (!subscriber.isInFlight(messageId)) throw InvalidAcknowledgmentException(messageId + " is not in flight for " + subscriberId); // not currently awaiting acknowledgment
        subscriber.clearInFlight(messageId);                                 // done, stop tracking it
        for (auto& obs : observers) obs->onMessageAcknowledged(subscriberId, messageId); // notify
    }

    void advanceTick() { currentTick++; } // advances the deterministic logical clock by one step

    void checkForRedelivery() {
        for (auto& pair : subscribers) {                                                                            // scan every subscriber
            Subscriber& subscriber = pair.second;
            vector<string> timedOut;                                                                                    // ids that have timed out this sweep
            for (auto& entry : subscriber.inFlightDeliveredAtTick) {                                                       // scan every in-flight message
                if (currentTick-entry.second >= timeoutTicks) timedOut.push_back(entry.first); // this one has waited too long
            }
            for (auto& messageId : timedOut) {                                                                            // handle each timed out message
                Message message = subscriber.inFlightMessages.at(messageId);                                                 // the message itself
                subscriber.clearInFlight(messageId);                                                                            // no longer in flight
                message.incrementDeliveryCount();                                                                                 // this counts as a failed attempt
                if (message.deliveryCount > maxRetries) {                                                                          // retries exhausted
                    subscriber.addToDeadLetter(message);                                                                               // set it aside permanently
                    for (auto& obs : observers) obs->onMessageDeadLettered(subscriber.subscriberId, message);
                } else {                                                                                                               // still has attempts left
                    subscriber.requeueFront(message);                                                                                     // redeliver it next
                }
            }
        }
    }
};

