}
class InvalidAcknowledgmentException extends RuntimeException {
    public InvalidAcknowledgmentException(String msg) { super(msg); }
}

class PubSubService {
    private final Map<String, Subscriber> subscribers = new LinkedHashMap<>();
    private final List<DeliveryObserver> observers = new ArrayList<>();
    private final ExactTopicMatchingStrategy exactStrategy = new ExactTopicMatchingStrategy();
    private final WildcardTopicMatchingStrategy wildcardStrategy = new WildcardTopicMatchingStrategy();
    private int currentTick = 0;
    private final int maxRetries;
    private final int timeoutTicks;

    public PubSubService(int maxRetries, int timeoutTicks) {
        this.maxRetries = maxRetries;
        this.timeoutTicks = timeoutTicks;
    }

    public void addObserver(DeliveryObserver observer) { observers.add(observer); }

    public Subscriber subscriberFor(String subscriberId) {
        return subscribers.computeIfAbsent(subscriberId, Subscriber::new);
    }

    private TopicMatchingStrategy strategyFor(String pattern) {
        return pattern.contains("*") ? wildcardStrategy : exactStrategy;
    }

    public void subscribe(String subscriberId, String pattern) {
        if (pattern == null || pattern.trim().isEmpty()) {
            throw new InvalidTopicPatternException("Topic pattern must not be blank");
        }
        subscriberFor(subscriberId).addPattern(pattern);
    }

    public int publish(String topic, String payload, MessageIdFactory factory) {
        int matchedCount = 0;
        for (Subscriber subscriber : subscribers.values()) {
            boolean matched = false;
            for (String pattern : subscriber.getTopicPatterns()) {
                if (strategyFor(pattern).matches(pattern, topic)) { matched = true; break; }
            }
            if (matched) {
                Message message = new Message(factory.nextMessageId(), topic, payload);
                subscriber.enqueue(message);
                matchedCount++;
            }
        }
        for (DeliveryObserver obs : observers) obs.onMessagePublished(topic, matchedCount);
        return matchedCount;
    }

    public synchronized Message receive(String subscriberId) {
        Subscriber subscriber = subscriberFor(subscriberId);
        if (!subscriber.hasPending()) {
            throw new EmptyQueueException("No pending messages for " + subscriberId);
        }
        Message message = subscriber.dequeueFront();
        subscriber.markInFlight(message, currentTick);
        return message;
    }

    public void acknowledge(String subscriberId, String messageId) {
        Subscriber subscriber = subscriberFor(subscriberId);
        if (!subscriber.isInFlight(messageId)) {
            throw new InvalidAcknowledgmentException(messageId + " is not in flight for " + subscriberId);
        }
        subscriber.clearInFlight(messageId);
        for (DeliveryObserver obs : observers) obs.onMessageAcknowledged(subscriberId, messageId);
    }

    public void advanceTick() { currentTick++; }

    public void checkForRedelivery() {
        for (Subscriber subscriber : subscribers.values()) {
            List<String> timedOut = new ArrayList<>();
            for (Map.Entry<String, Integer> entry : subscriber.getInFlightDeliveredAtTick().entrySet()) {
                if (currentTick-entry.getValue() >= timeoutTicks) timedOut.add(entry.getKey());
            }
            for (String messageId : timedOut) {
                Message message = subscriber.getInFlightMessages().get(messageId);
                subscriber.clearInFlight(messageId);
                message.incrementDeliveryCount();
                if (message.getDeliveryCount() > maxRetries) {
                    subscriber.addToDeadLetter(message);
                    for (DeliveryObserver obs : observers) obs.onMessageDeadLettered(subscriber.getSubscriberId(), message);
                } else {
                    subscriber.requeueFront(message);
                }
            }
        }
    }
}

